package com.codepilot1c.core.edt.development;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class DirectClientTimingTest {
 @Test public void defaultBudgetsAndStartupRemainSeparate(){assertEquals(25,DirectClientTiming.seconds(Map.of()));assertEquals(35,DirectClientTiming.replySeconds(Map.of()));assertEquals(105,DirectClientTiming.replySeconds(Map.of("operation","ready","startup_timeout_ms",90000)));}
 @Test public void callerCanIncreaseTheWholePacketAndReplyBudgets(){assertEquals(90,DirectClientTiming.seconds(Map.of("operation_timeout_s",90.0)));assertEquals(100,DirectClientTiming.replySeconds(Map.of("operation_timeout_s",90)));assertEquals(310,DirectClientTiming.replySeconds(Map.of("operation_timeout_s",300)));DirectClientTiming.validate(Map.of("operation_timeout_s",90,"wait_timeout_ms",60000));}
 @Test public void invalidOrInconsistentBudgetsAreRejected(){for(Object value:List.of(0,4,301,true,5.5,"90")){assertThrows(IllegalArgumentException.class,()->DirectClientTiming.seconds(Map.of("operation_timeout_s",value)));}assertThrows(IllegalArgumentException.class,()->DirectClientTiming.validate(Map.of("wait_timeout_ms",60000)));}
 @Test public void wholeBatchBudgetIsInheritedByStepsBeforeAnyLaunch(){var step=Map.<String,Object>of("action","wait","expected_window","Map","wait_timeout_ms",60000);var a=new LinkedHashMap<String,Object>(Map.of("action","batch","snapshot_id","preflight","expected_window","Map","steps",List.of(step)));assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(a));a.put("operation_timeout_s",90);DirectTestClientService.validateAction(a);a.put("steps",List.of(Map.of("action","wait","expected_window","Map","operation_timeout_s",90)));assertThrows(IllegalArgumentException.class,()->DirectTestClientService.validateAction(a));}
}
